// Field type definitions, mirroring the whoosh.fields interface used by the
// source script: ID, TEXT, KEYWORD and NUMERIC.

class FieldType {
  constructor(name, options = {}) {
    this.name = name;
    this.stored = Boolean(options.stored ?? false);
  }

  toString() {
    if (this.stored) {
      return `${this.name}(stored=True)`;
    }
    return this.name;
  }
}

export function ID(options = {}) {
  return new FieldType('ID', options);
}

export function TEXT(options = {}) {
  return new FieldType('TEXT', options);
}

export function KEYWORD(options = {}) {
  return new FieldType('KEYWORD', options);
}

export function NUMERIC(options = {}) {
  return new FieldType('NUMERIC', options);
}

