// Schema implementation mirroring whoosh.fields.Schema string behavior.
// Its repr is "<Schema: ['name1', 'name2', ...]>" with field names sorted.

export class Schema {
  constructor(fields = {}) {
    this.fields = { ...fields };
  }

  names() {
    return Object.keys(this.fields).sort();
  }

  toString() {
    const rendered = this.names()
      .map((name) => `'${name}'`)
      .join(', ');
    return `<Schema: [${rendered}]>`;
  }
}

