// Minimal argparse-compatible parser for the options used by test2:
//   -h / --help   show help and exit 0
//   --a A         required string argument
// Mirrors Python argparse: usage/error text on stderr, exit code 2 on error,
// support for "--a value" and "--a=value" forms.

import { basename } from 'node:path';

function looksLikeNegativeNumber(token) {
  return /^-\d+$|^-\d*\.\d+$/.test(token);
}

function isOptionToken(token) {
  return token.startsWith('-') && token !== '-' && !looksLikeNegativeNumber(token);
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog ?? basename(process.argv[1] ?? 'test2.mjs');
  }

  usage() {
    return `usage: ${this.prog} [-h] --a A`;
  }

  helpText() {
    return [
      this.usage(),
      '',
      'options:',
      '  -h, --help  show this help message and exit',
      '  --a A',
    ].join('\n');
  }

  error(message) {
    process.stderr.write(`${this.usage()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parse(argv) {
    const args = { a: undefined };
    const unrecognized = [];

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (token === '-h' || token === '--help') {
        process.stdout.write(`${this.helpText()}\n`);
        process.exit(0);
      }

      if (token === '--a' || token.startsWith('--a=')) {
        let value;
        if (token.startsWith('--a=')) {
          value = token.slice('--a='.length);
        } else {
          const next = argv[i + 1];
          if (next === undefined || isOptionToken(next)) {
            this.error('argument --a: expected one argument');
          }
          value = next;
          i += 1;
        }
        args.a = value;
        continue;
      }

      unrecognized.push(token);
    }

    if (unrecognized.length > 0) {
      this.error(`unrecognized arguments: ${unrecognized.join(' ')}`);
    }

    if (args.a === undefined) {
      this.error('the following arguments are required: --a');
    }

    return args;
  }
}

