// Entry point mirroring /workspace/dataset/whoosh/test2.py.
// Parses the required --a argument, builds the schema and prints it exactly
// like whoosh's Schema repr.

import { ArgumentParser } from './argparse.mjs';
import { Schema } from './schema.mjs';
import { ID, TEXT, KEYWORD, NUMERIC } from './fields.mjs';

const parser = new ArgumentParser();
const args = parser.parse(process.argv.slice(2));

const schema = new Schema({
  id: ID({ stored: true }),
  title: TEXT({ stored: true }),
  tags: KEYWORD(),
  price: NUMERIC({ stored: true }),
}); // Create schema with multiple field types
console.log(schema.toString());

export { args };

